CREATE VIEW std_inventory_game_ready AS SELECT s.* EXCLUDE (igdb_id, opencritic_id), CASE  WHEN (EXISTS(SELECT 1 FROM dq_external_id_conflicts AS c WHERE ((c.id_type = 'IGDB') AND (c.external_id = CAST(s.igdb_id AS VARCHAR))))) THEN (NULL) ELSE s.igdb_id END AS igdb_id, CASE  WHEN (EXISTS(SELECT 1 FROM dq_external_id_conflicts AS c WHERE ((c.id_type = 'OPENCRITIC') AND (c.external_id = CAST(s.opencritic_id AS VARCHAR))))) THEN (NULL) ELSE s.opencritic_id END AS opencritic_id FROM std_inventory_curated AS s;
